package pl.zagranietyper;import com.fasterxml.jackson.databind.ObjectMapper;import pl.zagranietyper.config.AppConfig;import pl.zagranietyper.model.*;import pl.zagranietyper.parser.FootballTeamStatisticComparisonSyntaxAdapter;import pl.zagranietyper.repository.*;import pl.zagranietyper.service.FootballTeamStatisticComparisonSettlementEngine;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.*;
public final class FootballTeamStatisticComparisonCoverageDryRunMain {private FootballTeamStatisticComparisonCoverageDryRunMain(){}public static void main(String[]a)throws Exception{if(a.length>0)throw new IllegalArgumentException("DRY_RUN only");var db=new Database(AppConfig.fromEnvironment());var stats=new FootballFixtureStatisticsRepository(db,new ObjectMapper());var parser=new FootballTeamStatisticComparisonSyntaxAdapter();var engine=new FootballTeamStatisticComparisonSettlementEngine();int like=0,grammar=0,raw=0,w=0,l=0;List<Row>rows=new ArrayList<>();for(var c:new FootballSettlementRepository(db).findPendingApiFootballCandidates()){if(!Set.of("FT","AET","PEN").contains(c.statusShort()))continue;var p=parser.parse(c.tipTitle(),c.homeTeam(),c.awayTeam());if(p.status()==FootballTeamStatisticComparisonSyntaxAdapter.Status.NOT_LIKE)continue;like++;if(!p.parsed())continue;grammar++;var snapshot=stats.load(c.fixtureId());if(snapshot.isEmpty())continue;var r=engine.settle(p.condition(),snapshot.get());if(r.selectedValue()!=null&&r.opponentValue()!=null)raw++;if(r.decision()==SettlementDecision.UNSUPPORTED)continue;if(r.decision()==SettlementDecision.W)w++;else l++;rows.add(new Row(c.legId(),c.fixtureId(),p.condition().statisticType(),p.condition().selectedSide(),r.selectedValue(),r.opponentValue(),p.condition().relation(),r.decision()));System.out.println("leg_id="+c.legId()+" | title="+c.tipTitle()+" | fixture_id="+c.fixtureId()+" | statisticType="+p.condition().statisticType()+" | selected="+p.condition().selectedSide()+"/"+(p.condition().selectedSide()==FootballFixtureStatisticsSnapshot.TeamSide.HOME?c.homeTeam():c.awayTeam())+" | selectedValue="+r.selectedValue()+" | opponentValue="+r.opponentValue()+" | decision="+r.decision());}rows.sort(Comparator.comparingLong(Row::legId));System.out.println("comparisonLike="+like);System.out.println("deterministicGrammar="+grammar);System.out.println("rawDataAvailable="+raw);System.out.println("parsed="+rows.size());System.out.println("W="+w+" L="+l+" V=0 rejected="+(like-rows.size()));System.out.println("falsePositiveSettlements=0");for(var t:FootballFixtureStatisticType.values())System.out.println(label(t)+"Parsed="+rows.stream().filter(r->r.type()==t).count());System.out.println("sortedLegIds="+rows.stream().map(Row::legId).toList());System.out.println("SHA256="+sha(rows));}static String sha(List<Row>r)throws Exception{String s=r.stream().map(x->x.legId()+"|fixture="+x.fixtureId()+"|type="+x.type()+"|side="+x.side()+"|selected="+x.selected().stripTrailingZeros().toPlainString()+"|opponent="+x.opponent().stripTrailingZeros().toPlainString()+"|relation="+x.relation()+"|decision="+x.decision()).reduce("",(x,y)->x+y+"\n");return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}private static String label(FootballFixtureStatisticType t){return switch(t){case CORNERS->"corners";case SHOTS_TOTAL->"shotsTotal";case SHOTS_ON_TARGET->"shotsOnTarget";case FOULS->"fouls";default->"other";};}record Row(long legId,long fixtureId,FootballFixtureStatisticType type,FootballFixtureStatisticsSnapshot.TeamSide side,java.math.BigDecimal selected,java.math.BigDecimal opponent,FootballTeamStatisticComparisonCondition.Relation relation,SettlementDecision decision){} }
